import{c as t,Q as o,j as r,m as i}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"楚辞","description":"","frontmatter":{"id":"chuci","title":"楚辞","author":"屈原等","dynasty":"战国","cover":"/covers/chuci.jpg","sort":4,"literaryValue":"《楚辞》是中国最早的浪漫主义诗歌总集，以屈原的《离骚》为代表，开创了浪漫主义文学的先河，与《诗经》并称\\"风骚\\"。"},"headers":[],"relativePath":"books/shici/chuci.md","filePath":"books/shici/chuci.md"}'),e={name:"books/shici/chuci.md"};function s(n,a,l,h,p,c){return o(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="楚辞" tabindex="-1">楚辞 <a class="header-anchor" href="#楚辞" aria-label="Permalink to &quot;楚辞&quot;">​</a></h1><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>《楚辞》是中国文学史上第一部浪漫主义诗歌总集，相传是屈原创作的一种新诗体。&quot;楚辞&quot;的名称，西汉初期已有之，至刘向乃编辑成集。东汉王逸作章句。原收战国楚人屈原、宋玉及汉代淮南小山、东方朔、王褒、刘向等人辞赋共十六篇。后王逸增入己作《九思》，成十七篇。全书以屈原作品为主，其余各篇也是承袭屈赋的形式。</p><p>《楚辞》运用楚地的文学样式、方言声韵，叙写楚地的山川人物、历史风情，具有浓厚的地方特色。全书以屈原作品为主，其余各篇也是承袭屈赋的形式。以其运用楚地的文学样式、方言声韵，叙写楚地的山川人物、历史风情，具有浓厚的地方特色，故名《楚辞》，对后世诗歌产生深远影响。</p><h2 id="离骚-节选" tabindex="-1">离骚（节选） <a class="header-anchor" href="#离骚-节选" aria-label="Permalink to &quot;离骚（节选）&quot;">​</a></h2><p><strong><a href="/books/shici/chuci/1.html">查看详情</a></strong></p><p><strong>屈原</strong></p><p>帝高阳之苗裔兮，朕皇考曰伯庸。 摄提贞于孟陬兮，惟庚寅吾以降。 皇览揆余初度兮，肇锡余以嘉名： 名余曰正则兮，字余曰灵均。</p><p>纷吾既有此内美兮，又重之以修能。 扈江离与辟芷兮，纫秋兰以为佩。 汩余若将不及兮，恐年岁之不吾与。 朝搴阰之木兰兮，夕揽洲之宿莽。 日月忽其不淹兮，春与秋其代序。 惟草木之零落兮，恐美人之迟暮。 不抚壮而弃秽兮，何不改乎此度？ 乘骐骥以驰骋兮，来吾道夫先路！</p><p>长太息以掩涕兮，哀民生之多艰。 余虽好修姱以鞿羁兮，謇朝谇而夕替。 既替余以蕙纕兮，又申之以揽茝。 亦余心之所善兮，虽九死其犹未悔。 怨灵修之浩荡兮，终不察夫民心。 众女嫉余之蛾眉兮，谣诼谓余以善淫。 固时俗之工巧兮，偭规矩而改错。 背绳墨以追曲兮，竞周容以为度。</p><p>路漫漫其修远兮，吾将上下而求索。</p><h2 id="九歌·湘夫人" tabindex="-1">九歌·湘夫人 <a class="header-anchor" href="#九歌·湘夫人" aria-label="Permalink to &quot;九歌·湘夫人&quot;">​</a></h2><p><strong><a href="/books/shici/chuci/2.html">查看详情</a></strong></p><p><strong>屈原</strong></p><p>帝子降兮北渚，目眇眇兮愁予。 袅袅兮秋风，洞庭波兮木叶下。 登白薠兮骋望，与佳期兮夕张。 鸟何萃兮蘋中，罾何为兮木上？</p><p>沅有芷兮澧有兰，思公子兮未敢言。 荒忽兮远望，观流水兮潺湲。 麋何食兮庭中？蛟何为兮水裔？ 朝驰余马兮江皋，夕济兮西澨。 闻佳人兮召予，将腾驾兮偕逝。</p><p>筑室兮水中，葺之兮荷盖。 荪壁兮紫坛，播芳椒兮成堂。 桂栋兮兰橑，辛夷楣兮药房。 罔薜荔兮为帷，擗蕙櫋兮既张。 白玉兮为镇，疏石兰兮为芳。 芷葺兮荷屋，缭之兮杜衡。</p><p>合百草兮实庭，建芳馨兮庑门。 九嶷缤兮并迎，灵之来兮如云。 捐余袂兮江中，遗余褋兮澧浦。 搴汀洲兮杜若，将以遗兮远者。 时不可兮骤得，聊逍遥兮容与。</p><h2 id="九歌·山鬼" tabindex="-1">九歌·山鬼 <a class="header-anchor" href="#九歌·山鬼" aria-label="Permalink to &quot;九歌·山鬼&quot;">​</a></h2><p><strong><a href="/books/shici/chuci/3.html">查看详情</a></strong></p><p><strong>屈原</strong></p><p>若有人兮山之阿，被薜荔兮带女萝。 既含睇兮又宜笑，子慕予兮善窈窕。 乘赤豹兮从文狸，辛夷车兮结桂旗。 被石兰兮带杜衡，折芳馨兮遗所思。</p><p>余处幽篁兮终不见天，路险难兮独后来。 表独立兮山之上，云容容兮而在下。 杳冥冥兮羌昼晦，东风飘兮神灵雨。 留灵修兮憺忘归，岁既晏兮孰华予？</p><p>采三秀兮于山间，石磊磊兮葛蔓蔓。 怨公子兮怅忘归，君思我兮不得闲。 山中人兮芳杜若，饮石泉兮荫松柏， 君思我兮然疑作。</p><p>雷填填兮雨冥冥，猨啾啾兮狖夜鸣。 风飒飒兮木萧萧，思公子兮徒离忧。</p><h2 id="天问-节选" tabindex="-1">天问（节选） <a class="header-anchor" href="#天问-节选" aria-label="Permalink to &quot;天问（节选）&quot;">​</a></h2><p><strong><a href="/books/shici/chuci/4.html">查看详情</a></strong></p><p><strong>屈原</strong></p><p>曰：遂古之初，谁传道之？ 上下未形，何由考之？ 冥昭瞢暗，谁能极之？ 冯翼惟象，何以识之？ 明明暗暗，惟时何为？ 阴阳三合，何本何化？</p><p>圜则九重，孰营度之？ 惟兹何功，孰初作之？ 斡维焉系，天极焉加？ 八柱何当，东南何亏？ 九天之际，安放安属？ 隅隈多有，谁知其数？</p><h2 id="艺术特色" tabindex="-1">艺术特色 <a class="header-anchor" href="#艺术特色" aria-label="Permalink to &quot;艺术特色&quot;">​</a></h2><p>《楚辞》的艺术特色主要体现在以下几个方面：</p><ol><li><strong>浪漫主义精神</strong>：想象丰富，感情奔放，充满神话色彩</li><li><strong>楚地特色</strong>：运用楚地方言，描写楚地风物</li><li><strong>句式灵活</strong>：突破四言限制，句式长短不拘</li><li><strong>象征手法</strong>：大量运用香草美人象征高洁品格</li><li><strong>抒情性强</strong>：直抒胸臆，情感浓烈</li></ol><h2 id="影响与价值" tabindex="-1">影响与价值 <a class="header-anchor" href="#影响与价值" aria-label="Permalink to &quot;影响与价值&quot;">​</a></h2><p>《楚辞》是中国文学的瑰宝，对后世产生了深远影响：</p><ul><li><strong>文学传统</strong>：开创了中国浪漫主义文学传统</li><li><strong>诗歌形式</strong>：为后世辞赋、骈文的发展奠定了基础</li><li><strong>文化精神</strong>：体现了屈原的爱国主义精神和高洁品格</li><li><strong>语言艺术</strong>：丰富了汉语的表现力，许多诗句成为千古名句</li></ul>',36)])])}const g=t(e,[["render",s]]);export{u as __pageData,g as default};
